"""Shared decorators for ASR and TTS provider connections.

Connection timing stays span-only: connect/disconnect latency is visible in
traces, while metrics carry only unexpected connection failures through
``rasa.voice.operation.failures``.
"""

from __future__ import annotations

import functools
from typing import Any, Callable, Dict, TypeVar, cast

from opentelemetry.trace import SpanKind

from rasa.tracing.voice.metrics import (
    VoiceComponent,
    VoiceOperation,
    record_operation_failure_metric,
)
from rasa.tracing.voice.spans.core import voice_stage_span

_ConnectMethod = TypeVar("_ConnectMethod", bound=Callable[..., Any])


def observed_connect(
    span_name: str,
    connect_attributes: Callable[[Any, bool], Dict[str, Any]],
    component: VoiceComponent,
) -> Callable[[_ConnectMethod], _ConnectMethod]:
    """Observe an engine's ``connect`` method.

    Connections after the first successful call are marked as reconnects on
    their spans.
    """

    def decorator(connect_method: _ConnectMethod) -> _ConnectMethod:
        @functools.wraps(connect_method)
        async def wrapper(self: Any, *args: Any, **kwargs: Any) -> Any:
            reconnect = getattr(self, "_voice_has_connected", False)
            try:
                with voice_stage_span(
                    span_name,
                    kind=SpanKind.CLIENT,
                    attributes=connect_attributes(self, reconnect),
                ):
                    result = await connect_method(self, *args, **kwargs)
            except Exception as error:
                record_operation_failure_metric(
                    component=component,
                    operation=VoiceOperation.CONNECT,
                    error=error,
                    provider=self.name(),
                )
                raise
            self._voice_has_connected = True
            return result

        # Provider override tests use this marker to detect missing decorators.
        wrapper._voice_connect_traced = True  # type: ignore[attr-defined]
        return cast(_ConnectMethod, wrapper)

    return decorator


def observed_disconnect(
    span_name: str,
    disconnect_attributes: Callable[[Any], Dict[str, Any]],
    component: VoiceComponent,
) -> Callable[[_ConnectMethod], _ConnectMethod]:
    """Observe an engine's ``close_connection`` method."""

    def decorator(close_method: _ConnectMethod) -> _ConnectMethod:
        @functools.wraps(close_method)
        async def wrapper(self: Any, *args: Any, **kwargs: Any) -> Any:
            try:
                with voice_stage_span(
                    span_name,
                    kind=SpanKind.CLIENT,
                    attributes=disconnect_attributes(self),
                ):
                    result = await close_method(self, *args, **kwargs)
            except Exception as error:
                record_operation_failure_metric(
                    component=component,
                    operation=VoiceOperation.DISCONNECT,
                    error=error,
                    provider=self.name(),
                )
                raise
            return result

        # Provider override tests use this marker to detect missing decorators.
        wrapper._voice_disconnect_traced = True  # type: ignore[attr-defined]
        return cast(_ConnectMethod, wrapper)

    return decorator
